const license = 'Release licence for authored records not yet selected; linked manufacturer documents retain their own rights.';
export const addedRecords = items.map(r => ({
  id: r.id, name: r.name, vendor: r.vendor, category: r.category,
  summary: `${r.vendor} ${r.category}. Model-family reference; select and verify the exact configuration before use.`,
  capabilities: r.capabilities, modules: r.modules,
  performance: 'Condition-specific performance has not been extracted into this record.',
  sources: [], evidenceLevel: 'curated-reference', license, verified: checked,
  completeness: {headSelection: 'Review source; family envelope may combine multiple heads', labware: 'Not fully extracted', accuracy: 'Not extracted', geometry: 'Not extracted', integration: 'Native/optional/external roles; exact device compatibility requires review'},
  upstream: null
}));
export const addedEvidence = items.map(r => {
  const kinds = new Map(r.sources.map(s => [s.id, s.kind]));
  return {id: r.id, summary: r.summary, sources: r.sources, gaps: r.gaps,
    claims: r.claims.map(x => ({evidence: evidenceFromSources(x.sourceIds.map(id => kinds.get(id))), ...x}))};
});
